// dr-backup.js
require('dotenv').config({ path: '.env.test' }); // or appropriate env

const fs = require('fs');
const crypto = require('crypto');

function buildSecretsPayload() {
  const payload = {
    databaseUrl: process.env.DATABASE_URL,
    // List specific keys, don’t just dump process.env
    apiKeys: {
      serviceA: process.env.SERVICE_A_API_KEY,
      serviceB: process.env.SERVICE_B_API_KEY,
      // ...
    },
    generatedAt: new Date().toISOString(),
  };

  // Basic validation: don’t produce a backup if required secrets are missing
  if (!payload.databaseUrl) {
    throw new Error('DATABASE_URL is missing; refusing to create backup');
  }

  return payload;
}

// Example: symmetric encryption with a strong key in a separate system.
// In real DR, this key should *not* live in the app env.
function encrypt(jsonString, key, iv) {
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  let encrypted = cipher.update(jsonString, 'utf8', 'base64');
  encrypted += cipher.final('base64');
  const authTag = cipher.getAuthTag().toString('base64');
  return { encrypted, iv: iv.toString('base64'), authTag };
}

async function main() {
  // In a real setup, `DR_BACKUP_KEY` should be provided by a secure, separate channel.
  const keyBase64 = process.env.DR_BACKUP_KEY;
  if (!keyBase64) {
    throw new Error('DR_BACKUP_KEY is not set; aborting backup creation');
  }

  const key = Buffer.from(keyBase64, 'base64');
  if (key.length !== 32) {
    throw new Error('DR_BACKUP_KEY must be 32 bytes (base64-encoded)');
  }

  const iv = crypto.randomBytes(12);

  const payload = buildSecretsPayload();
  const json = JSON.stringify(payload);
  const encrypted = encrypt(json, key, iv);

  const output = {
    algorithm: 'AES-256-GCM',
    ...encrypted,
  };

  fs.writeFileSync('dr-secrets-backup.json.enc', JSON.stringify(output, null, 2), {
    mode: 0o600,
  });

  console.log('DR backup created at dr-secrets-backup.json.enc');
}

main().catch(err => {
  console.error('Failed to create DR backup:', err.message);
  process.exitCode = 1;
});
```

